# -*- coding: utf-8 -*-
from pathlib import Path
import json,re,hashlib
BASE=Path('/Volumes/YSAigc/剧作项目/我不再做教父的大码人形抱枕/新版提示词_789与第三集补段_20261023')
SOURCE=BASE/'输入/EP08_当前批准稿.json'
src=json.loads(SOURCE.read_text(encoding='utf-8'))
rows=[]
phase_index={}
def add(n,title,env,size,angle,cam,phases,acting,frame,sound,issues=None):
 s=src[n-1]; dur=s['duration']
 assert s['shot']==n
 assert round(phases[0][0],4)==0 and abs(phases[-1][1]-dur)<1e-8
 for a,b in zip(phases,phases[1:]): assert a[1]==b[0], (n,a,b)
 assert all(a<b for a,b,t in phases)
 timeline='；'.join(f'{a:.2f}—{b:.2f}秒，{t}' for a,b,t in phases)+'。'
 dialogue=[]
 for d in s['dialogue']:
  delivery='画外同场对白' if d['delivery'].startswith('offscreen') else '同场原对白'
  if n in (12,33,35,48): delivery+='（切入纸面或反应镜后声画延续）'
  if d.get('continuation_of'): delivery+='，承接上一镜语意，仅说本镜片段，不重复前文'
  dialogue.append(f"{d['speaker']}（{delivery}）：\"{d['text']}\"。")
 audio=sound+'；'+(''.join(dialogue) if dialogue else '本镜无人物对白、无说话口型。')+'不加旁白、背景音乐或字幕。'
 appearance='人物外观、衣物及妆造仅沿本镜绑定资产，保留成年身份和既定体型。'+('男主衣物保持扣合、胸口遮盖。' if any('Matteo' in name for name in s['asset_names']) else '')
 text=f'**Shot {s["source_id"]}：{title}**\n\n时长：{dur:.2f}秒。\n环境氛围：{env}\n景别：{size}\n拍摄角度：{angle}\n摄像机运动：{cam}\n人物角色和运动：{timeline}\n人物表演：{acting}\n画面内容：竖屏9:16，真人电影写实，正常速率。{frame}{appearance}\n音频：{audio}'
 rows.append(dict(source_id=s['source_id'],duration=dur,asset_names=s['asset_names'],new_prompt=text,issues=issues or []))
 phase_index[s['source_id']]=phases

def checkpoint(start,end):
 target=[r for r in rows if start<=int(r['source_id'][-2:])<=end]
 name=f'EP08_新版提示词_{start:02d}-{end:02d}'
 for stem,data in [(name,target),('EP08_新版提示词',rows)]:
  (BASE/(stem+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
  (BASE/(stem+'.md')).write_text('\n\n---\n\n'.join(r['new_prompt']+('\n\n需核实：'+'；'.join(r['issues']) if r['issues'] else '') for r in data)+'\n',encoding='utf-8')
 print(f'checkpoint {start}-{end}: cumulative={len(rows)}',flush=True)

BED='Eliza旧卧室，窗外自然光与室内暗部沿批准画面，床、枕头、被面及家具采用场景资产，不添加新款色。'
ESTATE='傍晚庄园客厅，高窗冷光与既有暖灯相混，低茶几上的纸与杯清楚，人物暗部保留层次。'
APT='夜晚公寓小客厅，沿“客厅与入口”既定入户门、沙发及两侧灯柜，暖灯与安静室内环境保留，不新增城市落地窗。'
CAMPUS='18岁成年回忆，石砌校园、秋叶和原小路沐在温暖日光中；未有专用校园场景卡，按批准源空间文字建立。'
GARDEN='18岁成年回忆，源花园茶桌与花园椅处于明亮日光，茶具各有桌面承托；不假用其他场景卡。'
