add(1,'被面上的手缓缓攥紧',BED,'手部大特写（ECU）。','从床右通道向近侧被面俯拍；只取Eliza原入画的一只手与袖部，不新增另一只手。','固定俯拍，无额外推拉。',[(0,.84,'Eliza原本张开的手贴在同一被面上，指尖逐步向掌心收拢，带住指下的一小片被面'),(.84,1.16,'手合成拳后停住，拳侧仍由床面托着，保持同一抓点')],'未被回应的记忆使手指先紧、指节随后绷住；只通过抓握力度显出难受，不另加脸部或口型。','手在女主实际床右近侧，不把这只手接到床内侧男主身体。被面从指下聚拢，结尾拳头仍在原处，不把床品变成新图案。','被面被收紧的细小摩擦声、安静室内底声。',['批准稿未给此局部明确左右手；保持同一原入画手及镜位，不凭空交换手别。'])
add(2,'从紧拳切到看向身旁的人',BED,'手部特写硬切女主中近景（MCU），保留男主侧脸局部。','起段沿被面俯拍；后段从床右近枕外侧略俯拍Eliza，女主偏画面右，男主里侧侧脸留画面左缘。','两段机位各自固定，以硬切换景别，不以摄影机穿床转位。',[(0,.12,'承接上一镜拳头已攥住的终态，不再从张手重演'),(.12,.96,'硬切到枕上Eliza；她仍仰卧，只把眼睛及头部转向实际床左里侧的Matteo，男主原位不动，停在复杂的凝视上')],'Eliza先移眼再小幅转头，带着回想后的迟疑与难受；不开笑、不增加对白，男主只维持原侧脸。',BEDLOCK+'两人的后脑各由原枕承托；只转头而不翻身，不把床左里侧机械写成画面右侧。','极轻床品声及自然呼吸。',['已按批准位置锁修正旧正文“男主画右”的残留，未交换实际床位；内部切点是本次执行分配，非源帧测量。'])
add(3,'目光里的光慢慢退下',BED,'双人近景硬切女主眼部大特写（ECU）。','起段保持右通道同侧的双人枕区关系，Eliza近右、Matteo远左；后段只收Eliza眼鼻，视线仍指向戏内男主一侧。','固定双人近景后硬切固定眼部特写，不另加变焦。',[(0,.12,'承接Eliza已经侧头望男主的双人近景，身体仍并排仰卧'),(.12,.82,'硬切到她的眼鼻；她缓慢眨眼一次，再睁开时目光不再追索对方'),(.82,1.08,'眼睛停在同一戏内方向，维持空落的凝视')],'意识到距离没有改变，眼底期待先退，眼睑缓缓合开后留下失神；不让眼睛看摄影机，不加流泪或叹气。',BEDLOCK+'眼部特写没有另设身体位置，头仍落同一近侧枕位；男主不在切镜间换到她另一边。','安静室内底声，一次轻微正常呼吸。')
add(4,'把情绪压进交握的双手',BED,'眼部特写硬切双人中景（MS）。','从床右通道偏床尾略高取双人仰卧；女主近侧画面右，男主里侧画面左，床头在画面上方。','各段固定，硬切拉开视野，不作镜头滑移或身体形变。',[(0,.12,'延续女主眼部失神的近距离终态'),(.12,1.30,'硬切双人中景；Eliza轻抿双唇，把双手从身前聚拢，交握在自己腹前被面上，Matteo仍仰卧在里侧'),(1.30,1.72,'两人的肩背与后脑保持床垫、枕头承托；女主双手交握后不再松开')],'女主嘴唇先收住，随后把手指扣在一起，胸肩略紧；男主保持侧脸与原姿态，没有补安慰动作。',BEDLOCK+'女主的双手属于同一人并在被面上可见，男主手臂不冒充她的手；四肢及枕头落点连续。','床品轻响与室内底声。',['按实际床位重算双人全景屏幕坐标，去掉旧稿女左男右的镜像残留。'])
add(5,'闭眼压住情绪',BED,'双人中景硬切女主正面近景（CU）。','起段同侧床尾双人构图；后段在右通道近枕位置略俯，女主面部居中，枕头承托及男主里侧局部保持原关系。','硬切至固定略俯近景。',[(0,.12,'保留女主双手已在腹前交握、男主仍在里侧的中景'),(.12,1.24,'硬切到Eliza枕上近景；她闭上眼，胸口随一次克制的呼吸起伏，喉部轻动'),(1.24,1.60,'呼吸回落，双唇仍闭合，眼睛保持合着而身体不移动')],'她先主动闭眼，再把涌上的情绪压住，胸肩只有小幅自然起伏；不哭、不叹气、不夸张抽气。',BEDLOCK+'女主头肩仍在近侧原枕，手留腹前画外原处；只改变取景，不让她忽然坐起。','一次略不稳但克制的正常呼吸、极轻床品声。')
add(6,'把被面拉高挡住自己',BED,'女主近景硬切双人中景（MS）。','起段略俯女主闭眼面部；后段床右通道偏床尾同侧取两人，女主近右、男主远左。','两个固定机位硬切，保留动作全过程。',[(0,.12,'延续女主闭眼，双唇刚自然分开的近景，不重复呼吸反应'),(.12,1.40,'硬切中景；Eliza收下巴，用右手捏住身前被沿向上拉至下巴附近，左手留身前，不把男主的被面一同扯走；只由她自然说本镜原对白'),(1.40,1.72,'被沿最终停在胸前、下巴露在被沿上方；她保留原抓点，男主原位不动')],'羞窘先落在收下巴的小动作上，拉被时手指攥紧；声音轻而能听清，不配媚笑，也不把遮挡动作改成裸露动作。',BEDLOCK+'女主仰卧、肩背仍在床面；被面沿手部真实抓点移动，不自行升起，也不把她盖成无法说话。','拉动被面的柔软摩擦、同室自然底声。',['已实看源S06尾卡为女主右手拉被，左手保持身前；调整画面左右时不交换人物左右手。'])
add(7,'半坐着把问题问完',BED,'女主中近景（MCU），单一镜头。','床右通道偏床尾拍女主，女主近侧居中偏右，目光向画左里侧画外的Matteo。','固定中近景，不增加硬切。',[(0,.58,'Eliza承接胸前抓被的状态，空出的左肘与左掌依次撑住自己枕旁床面，臀部不离近侧原位，将肩背抬到原枕、床头能托住的半坐姿'),(.58,1.78,'她转头看实际里侧Matteo，胸前被沿由右手稳住，只接续本镜那一段原对白'),(1.78,2.08,'话尾说完后停在半坐、头朝男主的姿势，不重复前一句，不再把被子上提')],'她先稳住自己再开口，眼神显出脆弱和认真，句尾等待回应；无笑，不能把羞窘演成撒娇或故意挑逗。',BEDLOCK+'本镜男主在画外原里侧，不额外引用画内人物；女主半坐有肘掌及床头支撑，脚不凭空落地，不从仰卧瞬移成直坐。','支撑起身的轻微床品声、自然呼吸。',['源直接以半坐姿起镜；为承接上一镜仰卧，仅落实必要的原位支撑过渡，不增加起身离床。'])
add(8,'不回应她，只坐起露出得意',BED,'女主近景硬切过女主肩的男主近景（CU）。','前段女主在原近侧半坐；后段从她右外后方作真实过肩，女主近肩与侧脸虚在画面右下前景，里侧Matteo在画面左后。','固定近景硬切固定过肩，镜头始终在床右通道。',[(0,.16,'女主承接上一句已经结束的尾态，合上嘴唇，保持头朝男主，不重说问题'),(.16,1.70,'硬切过女主肩；Matteo先看着她停顿，保持沉默，只留一次轻的正常呼吸'),(1.70,3.50,'Matteo用自己肘、掌撑住里侧床面，收腹把上身缓慢带起，臀部仍在原里侧，不压住女主支撑手'),(3.50,4.24,'他坐稳后嘴角才勾出小幅得意的戏谑笑，女主前景仍静止')],'男主听见她的问话后没有立即回答；目光停一下，再坐起，笑意到嘴角才出现，显示笃定而非温柔回应。女主等待落空，只保持原侧脸。',BEDLOCK+'两人各自坐姿高度明确，前景肩确属近侧女主；男主坐起有手臂承重，头不仍固定贴枕，身体不越到近侧。','停顿中的正常呼吸、撑坐时床品轻响。',['批准动作段曾写轻叹、批准音频只留安静呼吸；依最新技能采用正常轻呼吸，保留停顿、坐起和得意表演。'])
add(9,'背向她坐到可离床的一侧',BED,'男主近景硬切双人中景（MS）。','前段保留男主里侧坐姿近景；后段从床右通道偏床尾取两人，女主在右后枕位，男主沿床长度移到足端右侧可落脚床沿，背向女主。','固定近景硬切固定同侧中景，不新增环绕。',[(0,.12,'承接Matteo已经坐起的得意表情，不再重演坐起'),(.12,1.64,'硬切双人中景；Matteo把双腿沿床长收向床尾，再转向右侧通道，使双脚落到可用地面，背向仍靠近侧原枕的Eliza；转身过程中接本镜原对白'),(1.64,2.16,'他用原入画的操作手在女主腿上方被面拍一下，随即手停在同一被面上，身体仍坐稳床沿')],'男主把背转过去，拍被的动作轻而随意，嘴角仍有自认她离不开自己的得意；女主停在枕上，不主动追过去。','床左靠墙里侧是男主起段的坐起位置，女主始终留床右近侧原枕位。离床路线为男主从里侧坐起位沿床长到足端、再转右通道，不能从床左穿墙落地。拍触落在被面覆盖的女主腿部，操作手始终归男主，不另按压身体。','收腿、落脚与拍被面的自然轻响。',['源时长内同时包含从床里侧移到足端右侧可离床床沿、拍被及对白，动作密度偏紧；保持2.16秒不延时，落点沿批准物理路线。','拍被手源未明确左右，保留同一操作手，不凭空交换手别。'])
add(10,'走到书桌旁仍回头嘲弄',BED,'双人中景硬切男主中景（MS）。','起段保留男主足端右侧床沿、女主近侧原枕；后段镜头在右通道可退让的同侧位置，男主到右侧原书桌，回头视线指向画左后方床上Eliza。','硬切后按源跟起作小幅上摇容纳男主起身，站定后固定；机位仍在右通道同侧，不加独立横移。',[(0,.12,'延续男主脚已落右通道、背对女主坐床沿的终态'),(.12,1.36,'硬切男主中景；他双脚踏实起身，沿右通道走到原书桌旁，不穿过床面或女主身体，接着说完同一句的本镜片段'),(1.36,1.76,'他在书桌边站定，只把头与肩稍向床上回转，保留得意神情')],'话尾带不以为意的确定感；回头只用侧目与嘴角，既不改成关心，也不新增亲近女主的动作。','女主仍靠原枕画外，男主书桌旁由双脚承重。床、书桌和床尾右入口各在原位，回看方向由书桌指回近侧枕，不与镜头对视；后镜可直接继承这个站姿。','原右通道脚步、衣料随行走的轻响。',['1.76秒的原行走与说话安排较紧，承接上镜双脚已经落地的状态，不加从床头重新下床或拉长时长。'])
