add(11,'书桌旁轻佻地评价她',BED,'男主中景硬切面部大特写（ECU）。','起段男主站原右书桌，回头朝床；后段仍从右通道同侧取回转后的脸，戏内女主在他视线所向的画外，不把他拍成正看镜头。','固定中景硬切固定面部大特写。',[(0,.14,'延续Matteo在书桌旁已回头的站姿，双脚不移动'),(.14,2.34,'硬切面部大特写；他略抬下巴，一侧眉梢轻挑，用轻佻、居高临下的口气说出本镜原对白'),(2.34,2.72,'句末保持傲慢的眼神与抬下巴，头肩不另转向别处')],'他把评价说得理所当然，眉梢与下巴的细微抬升使轻慢可见；不大笑、不加调情贴近，未出镜女主保持原枕位。','Matteo仍在书桌旁站着，颈肩朝床面一侧回转，紧景没有让他重新躺回床上。衣物扣合，面部取既定资产，不添加源纹身或裸露胸口。','同室自然底声及轻微衣料声。')
add(12,'支票旁攥住被面',BED,'男主面部特写硬切支票与手部特写（CU）。','前段沿上一镜男主回头面部；后段从床右通道上方向女主身前被面俯拍，纸张在原被面上，女主自己的手在旁。','两段均固定，硬切到纸面，不加投掷或跟落动作。',[(0,.14,'接男主已说完上一段的回头表情，开始本镜同一句的后续片段'),(.14,2.12,'硬切几张已经放在女主近侧被面上的支票；Eliza原本在旁的手收紧，把手指下的被面攥起，男主声音在同一房间画外延续'),(2.12,2.56,'她的手停在纸边，支票仍平放原处，既不拿起，也不推落')],'男主声音随意而轻慢；女主只用手指突然加重的抓力承受，拳侧不碰到或撕毁纸张。画内无脸部说话要求。','Eliza仍在床右近侧原枕，Matteo站在原右书桌旁，不能把画外男主按卧姿固定回枕头。支票是原镜支付纸件，已经落在女主被面，不把纸件改成另一种道具，也不补一次递出或扔下。女主的手与男主画外声音不混淆归属。','轻纸响、攥被面的摩擦，男主同场声音承接。',['支票怎样从书桌抵达被面的过程在批准稿切点外省略；本镜按批准首态“已经放好”执行，不擅加扔、递、拿动作。'])
add(13,'留下一句命令后走出门',BED,'支票特写硬切门框中景（MS）。','前段仍俯拍原支票与女主手；后段相机在床右通道朝床尾右入口，门框作前景，Matteo侧背影位于画面右侧可用门洞内。','固定纸面硬切固定门框构图，不让镜头越到墙后。',[(0,.14,'保持女主手在原支票旁攥住被面的状态，纸不再落下一遍'),(.14,2.56,'硬切门框中景；Matteo从原右书桌转向床尾右入口，沿右通道走出，说出本镜原对白，女主没有跟上'),(2.56,2.96,'只延续他侧背影通过门洞的末段，保留离开的方向，不在门边重新折返')],'男主一边离开一边结束谈话，语气带划定界限的冷淡；身体不为观察女主而停回来，女主只在前段手部承受。','路线从右书桌到床尾右门，不穿床、不穿左墙；男主双脚始终踩可用地面。首段纸与手的位置冻结，末段人物处于同一门框的离开动作中。','原通道脚步与门框附近轻响。')
add(14,'她在被下缩得更紧',BED+'黄昏暖光斜擦原墙面，室内留冷暗部。','门框中景硬切不露脸的被面中景（MS）。','起段同一床尾右门框；后段在床右通道侧拍近侧被窝，只见占用床位的隆起和既定旧熊玩偶局部。','固定门框硬切固定床侧，保留两个视点。',[(0,.22,'承接男主侧背影离开门洞的末段，不重演转身走出'),(.22,2.90,'硬切女主仍在同一床右近侧被下的中景；听到门外续句，被面先轻轻一颤，随后因她收拢身体而小幅缩紧'),(2.90,3.56,'被窝隆起停住，既定旧熊玩偶露出的部分留在原床面；男主继续画外，不再入镜')],'女主把受伤收进被下，只有被面的小颤与蜷紧可见；不能当成真实无人空床，也不加呜咽或抽泣。男主在画外把冷淡界限说完。','Eliza仍在床右近侧被下，Matteo已由床尾右门离开画外，不对他施加卧姿或枕位。女主的头、肩、躯干由原近侧床垫承托，被窝形状来自她本人的身体；旧玩偶始终为绑定熊形，不在切点变成别的动物。','被面细微摩擦、被下低而自然的呼吸、同场门外男主声音。')
add(15,'从被下孤身切到夜里独坐',APT,'占用床位的被面中景硬切公寓客厅全景（LS）。','前段床右通道仍对原近侧被窝；后段从公寓室内可用通道建立正面宽景，原门在中央墙面，Eliza独坐原右沙发。','固定床面硬切固定客厅全景，以明确场景和日夜切换表示省略。',[(0,.16,'保留前镜被窝隆起已停住的占床终态，不露脸，也不把她从被下移走'),(.16,1.84,'硬切到夜晚公寓小客厅；Eliza已经独自坐在原右沙发上，身形收拢、保持安静，门与两侧家具留在既定位置')],'无人来找她的空落落在缩小的坐姿与不动的目光里；不补等待来电、擦泪、望城市夜景或说话。','卧室到客厅为硬切时空省略，两段不连续搬运身体；后段臀背由右沙发坐垫、靠背承托，双脚或收腿按源姿态，不悬在扶手外。背景沿已绑定客厅与入口，不添加城市大窗。','公寓室内底声，极轻远处城市环境声。')
add(16,'抱膝把自己缩进沙发',APT,'公寓客厅全景硬切女主近景（CU）。','起段保持原右沙发全景；后段从室内通道朝同一坐位取女主居中，前后景仍是固定客厅家具。','硬切至固定近景，不新增手持摇摆或围绕。',[(0,.16,'延续Eliza已独坐原右沙发的宽景，身体没有离开座位'),(.16,1.84,'硬切近景；她把膝盖收近胸前，双臂绕住自己的腿，下巴随之落在膝上，臀背仍由坐垫和靠背承托'),(1.84,2.20,'手臂保持环腿的抓握，眼神低垂，缩成安静而退守的终态')],'空落使肩背向内收，下巴落稳后不再找人；眼神低而停滞，只留正常轻呼吸，不叹气、不配笑或口型。','近景沿同一沙发坐位收紧，人物与支撑面同时可理解；双膝不突然穿出手臂，两个手臂归女主，不额外出现第三只手。','自然轻呼吸、轻微坐垫与衣料声。')
add(17,'从独坐转入庄园续约会谈',ESTATE,'女主抱膝近景硬切庄园客厅大远景（ELS）。','前段仍是公寓原右沙发；后段从庄园大厅入口侧高一些建立同一会谈关系，Serafina位于画面左侧原红椅，Eliza在远处原绿沙发偏画面右，低茶几居二人之间。','固定近景硬切固定大远景；清楚换空间、换会谈时段，不靠形变变换造型。',[(0,.18,'延续公寓女主抱膝、下巴抵膝的近景终态'),(.18,2.72,'硬切傍晚庄园客厅全貌；现在的成年Eliza已按日常资产坐原绿沙发，Serafina在对面左红扶手椅坐着，合同已放在二人中间低茶几上'),(2.72,3.16,'二人各自坐稳，母亲的手在自己一侧合同附近停着，宽景留下正式而沉重的距离')],'公寓段仍是退守的孤独；会谈段两人克制不动，母亲占据从容位置，女主保持郑重，双方不新增开口或点头。',ESTLOCK+'近处圆桌花瓶不是本次会谈桌，不能把纸件移到圆桌；镜头在同一座位连线的入口侧。两段女主阶段与外观在明确硬切处变化，不同框混用。','大厅安静环境声与极轻室内器物声，不新增壁炉声。')
add(18,'母亲把续约纸推到她面前',ESTATE,'会谈大远景硬切合同与手部特写（CU）。','前段入口侧双人宽景；后段从同一会谈轴线入口半区上方俯拍低茶几，母亲操作手由画面左侧原红椅方向入画，纸滑向画面右侧女主方向。','固定宽景硬切固定俯拍，不把茶几换成另一张桌。',[(0,.16,'保留母亲左红椅、女主绿沙发和同一低茶几的完整关系'),(.16,1.48,'硬切纸面；Serafina原操作手贴住同一叠续约合同，沿桌面向女主侧平稳推送，杯碟仍在母亲自己座位侧'),(1.48,1.84,'合同停在女主侧、朝向女主；母亲的手在纸旁停一瞬，杯不跟着移动')],'母亲推纸干净而不容商量，手的停留带着等待服从的意味；女主不额外伸手接纸，也不在纸面镜添说话口型。',ESTLOCK+'手腕、前臂来源为Serafina原座位，不能从女主肩侧长出；合同一直受桌面承托，不悬空、不断裂，纸面取合同资产。手部装饰仅由角色资产决定。','纸在桌面滑动的清楚轻响，极轻杯碟声。',['源只说明母亲的操作手而未确认左右手，本稿锁所属及来向，不复制源首饰细节。'])
add(19,'低头面对熟悉的合同',ESTATE,'合同特写硬切女主中近景（MCU）。','前段仍沿桌面俯拍女主侧合同；后段从会谈轴线入口半区朝原绿沙发取Eliza，合同虚留前景下缘，女主看向自己前下方。','固定纸面硬切固定女主中近景。',[(0,.16,'同一合同停在女主侧；母亲尚入画的手沿原红椅来向收回，不把纸再推一次'),(.16,1.74,'硬切女主；Eliza仍坐绿沙发前缘，双手在自己身前交握，目光降到茶几上的那叠纸，神情逐渐凝重'),(1.74,2.08,'双手与低下的目光停住，合同留桌面原处，不移上膝')],'看见熟悉条款时，她先低眼，再把手指合紧；脸上沉下来，呼吸保持自然，没有替她加哭或苦笑。',ESTLOCK+'女主臀背始终有沙发承托，双手属于自己；母亲对坐画外位置冻结，纸的前景落点与前镜一致。','安静大厅底声、轻微纸面与衣料声。')
add(20,'母亲隔着杯口审视她',ESTATE,'女主中近景硬切隔茶几双人中景（MS）。','前段女主绿沙发低头；后段从女主外侧、会谈轴线同一入口半区拍母亲，女主背肩虚在画面右前，Serafina坐画面左后红椅，茶几在中间。','固定近景硬切固定关系中景，不越轴。',[(0,.16,'保持女主目光低落在合同上、双手交握的近景'),(.16,1.82,'硬切隔茶几关系镜；Serafina从自己一侧端起同一只茶杯，小口喝茶，目光越过杯口一直审视对面Eliza'),(1.82,2.28,'母亲停在端杯姿势，眼神冷而评量；女主前景仍坐稳，不转到母亲一侧')],'母亲杯口动作节制，眼睛持续打量，端茶成为从容施压；女主以安静的背肩接受，没有额外迎合回应。',ESTLOCK+'女主前景为坐姿背肩，摄影机高度与其坐姿相称；杯由母亲同一操作手端起，另一手不突然接杯，杯碟留原桌位。','小口喝茶、极轻瓷器及大厅环境声。')
checkpoint(11,20)

add(21,'她伸手翻开同一份条款',ESTATE,'隔茶几双人中景硬切女主与合同的俯拍近景。','起段仍母亲左后、女主右前；后段从入口同侧略高拍女主低头的面部与下方手、纸，前后不越过会谈轴线。','两个固定视点硬切；不把翻页演成镜头带纸穿过空间。',[(0,.18,'承接母亲喝茶、女主在对面坐着的关系中景，母亲杯仍在手'),(.18,2.08,'硬切女主俯近；Eliza从自己绿沙发前缘伸出原操作手，指腹捏住合同页角，只翻过一页，目光随着纸页降低'),(2.08,2.52,'翻开的页面平落回原纸叠，手停在新页上，女主头仍低着')],'先碰页边再翻页，手指慢而郑重，面部低下但没有新的哭笑反应；母亲画外仍坐原红椅，不替她翻纸。',ESTLOCK+'纸始终留女主侧桌面，翻页的手属于女主。近景同时保持低头与翻页的源表信息，面部在上、手纸在下，各由身体及桌面承托。','单页翻动的沙沙声，轻微茶杯及大厅环境声。',['源表写女主俯近，旧英文只列手部；按完整源表保留低头女主和翻页，使下一镜低头停格可接续，不新增表演。'])
add(22,'低头的短暂停格',ESTATE,'女主近景，闪回前短暂停格。','沿上一镜女主俯近关系，绿沙发、茶几纸件及手部落点不变，目光停在自己前下方合同。','固定停格，不推近，不加额外切镜或身体动作。',[(0,.44,'保持Eliza低头看合同的同一帧姿态，翻页已经结束，手停原新页上，作为回忆切入前的短暂留白')],'本镜只留凝住的低头神情，不再增加眨眼、抬头、抓手、起身或说话。',ESTLOCK+'停格只冻结原姿态，不提前改变年龄与场景；女主仍在坐垫上，合同仍在桌上。','极轻大厅环境底声，不加拟制音效。',['源同时标定格与轻微呼吸/眼睑移动，二者不可同为真正单帧；按源表0.44秒停格执行，不另扩动作。'])
add(23,'十八岁抱书走向校园',CAMPUS,'全身至中景的单人跟拍。','摄影机在原校园小路一侧平视略侧，18岁Eliza沿路径行进，塔楼在她行进前上方的戏内空间。','缓慢横移跟随，保持与原路径平行，不把行走改成原地推镜。',[(0,.64,'18岁Eliza双臂怀抱原书本，沿原石砌校园小路自然行走，脚掌依次在路面落地'),(.64,1.42,'继续同一路线行走，她把头抬向前上方校园建筑，手臂仍稳住胸前书本'),(1.42,1.76,'保持抬起的目光与向前的步态，让原横移跟拍接到下一镜驻足')],'年轻的希望先在抬头与亮起来的目光中出现，身体自然挺直；不是28岁床上情绪，也不对镜头微笑搭话。','仅用本镜18岁成年Eliza资产，保持原大码体型。校园建筑、秋叶和小路沿批准源空间，书本由双臂承托，不在走动中换到另一手或消失。','自然脚步、轻风与远处鸟声。')
add(24,'停在塔楼前仰望',CAMPUS,'塔楼前单人中景（MS）。','摄影机在同一小路侧略低，取Eliza与身后上方石砌塔楼；她的视线越过镜头上方看真实塔楼，不看镜头。','轻微缓推，保留源略仰方向，镜头不环绕。',[(0,.62,'Eliza承接上一镜步态，最后一步在原小路站稳，双脚承重，书本仍抱在胸前'),(.62,1.94,'她微抬下巴望向塔楼上部，眼里显出惊喜与希望，嘴角自然形成源稿的轻微笑意'),(1.94,2.48,'保持抬头仰望和抱书终态，身体不再继续走远')],'希望是抬眼后逐渐浮出的轻微笑意，脸部放松而真诚；不夸张张嘴，不加台词，不把视线落在摄影机。','18岁成年阶段、原校园路面和塔楼保持一致，双手一直稳住书本，脚不悬空；没有校园场景图时不伪称已绑定其他门、走廊。','轻风、远处鸟声与停止的脚步。')
add(25,'从明亮塔楼前切进深拱廊',CAMPUS+'后段转入同一校园的石拱廊，前景深色拱形与后方亮处保持原明暗反差。','亮处单人中景硬切石拱廊纵深中景。','前段沿塔楼前略低机位；后段摄影机在拱廊出口一侧沿廊轴取景，Eliza抱书在纵深中央，向出口和摄影机方向走，眼睛看前行路线而非镜头。','硬切后沿廊轴作轻微缓推，保留源缓慢前移，不增加旋转或架空穿墙。',[(0,.24,'保留Eliza在亮处抬头、带微小笑意的驻足终态'),(.24,1.02,'硬切到深色石拱作前框的拱廊；同一18岁Eliza仍抱书站在纵深原位，先稳定前行方向'),(1.02,3.60,'她沿拱廊原中轴向出口走来，从暗处朝亮处移动，书本一直抱稳，走路与缓推连续到镜末')],'对未来的认真藏在稳步向前与不躲闪的目光里，原亮处的希望接成专注；不加新担忧或口型。','同一18岁成年资产贯穿两个段落，明确硬切变换地点。石拱廊不替换成庄园木门空间；双脚踏石地，双臂托书，不变脸变体型，不将站位形变到出口。','石拱下脚步的轻回声与自然风声。')
add(26,'从校园行进切到花园倒茶',GARDEN,'拱廊中景硬切茶壶与杯的俯拍特写（CU）。','前段仍沿石拱廊出口看少女前行；后段俯拍原花园茶桌，18岁Eliza站桌侧，Serafina坐自己的椅位，杯在母亲座位侧。','前段接原轻推；硬切后固定俯拍茶流，不把两处身体连续搬运。',[(0,.16,'承接Eliza抱书在石拱廊中向前走的末段，不再重新起步'),(.16,1.54,'硬切花园茶桌；18岁Eliza已在桌侧站立并略俯身，一只手握茶壶柄，另一只手稳住壶盖，壶嘴准确对准坐着的Serafina面前原杯，细茶流落进杯中'),(1.54,1.84,'她回正壶身停止茶流，把壶底落向桌面原可放位置，杯仍由原杯碟和桌面承托')],'倒茶时眼神、手势都专注，动作带认真而恭敬的讨好；不加笑话、对白或夸张弯腰。','18岁Eliza与母亲仅按各自角色资产出现，校园到茶会为明确硬切。壶柄手与壶盖手属于同一少女，母亲没有同时拿着被倒的杯；壶、杯、杯碟保持真实重力与接触。','原茶流入杯的轻声、壶底接桌轻响与花园鸟声。',['源未给倒茶双手的左右侧，本稿保持原一手握柄、另一手稳盖的分工，不凭空增加或互换手。'])
add(27,'她站着，母亲只从容喝茶',GARDEN,'倒茶特写硬切母亲侧面中景（MS）。','前段花园桌面俯拍；后段在原茶桌外侧平视略侧拍坐着的Serafina，18岁Eliza保持画面左边原站位，二人眼高差真实保留。','固定茶具特写硬切固定侧面中景。',[(0,.20,'承接倒茶尾段的壶身回正和壶底即将落桌，不把已停的茶流重新倒一次'),(.20,2.38,'硬切侧面中景；Eliza仍站桌旁，茶壶已由桌面托住；Serafina从自己的杯碟端起刚盛好的原杯，矜持地小口喝茶'),(2.38,3.00,'母亲端杯停着，神情高贵而疏离；少女仍在原站位，不绕到母亲身后')],'母亲接受服务的动作理所当然，目光不追着少女，喝茶后没有温柔回报；少女只保持恭敬等待，不增加讨好笑容。','母亲臀背由原椅承托、少女双脚落地；杯由母亲原端杯手持着，壶由桌面支撑，没有漂浮。花园不是庄园室内，不能带入客厅绿沙发。','小口喝茶的自然轻声、极轻瓷器声与花园环境。')
add(28,'双手递出已签文件',GARDEN,'母亲侧面中景硬切交接手部特写（CU）。','前段保持母亲坐、少女站左侧的茶桌关系；后段从同一侧取纸与双方手，少女双手从自己站位侧递出，母亲从自己座位一侧接。','固定中景硬切固定交接插镜，不加递纸飞行跟拍。',[(0,.12,'保持母亲端杯喝茶结束、少女仍站桌侧的中景尾态'),(.12,.98,'硬切手部特写；少女双手托着已签文件递向坐着的母亲，母亲原接纸手握住可及纸边，少女等对方接稳后才松开'),(.98,1.20,'文件重量完全移交给母亲，少女的双手沿原来向退出，纸不落地')],'少女递纸郑重，等对方握稳才放手，母亲接取干净；不额外握手、鞠躬或说话。','18岁成年女主到本条为止。回忆中已签文件按批准纸件外观，交接时纸有双手承托，不把纸瞬移为现在茶几上未签的续约场面；母亲只用原接纸手，不让持杯手穿纸。','纸张交接的轻微摩擦、花园环境底声。',['前镜端杯到本镜接纸可由另一只空手接取；保留源接纸手，不擅加完整放杯动作，切点外的手部状态不编成额外表演。'])
add(29,'从旧日递纸切回冷淡的续约',ESTATE,'花园交接手部特写硬切现时桌面合同特写（CU）。','前段只留母亲已经接稳的旧文件与其手，不追加18岁少女正脸；后段在庄园会谈轴线入口同半区上方俯拍低茶几，母亲的手仍从左红椅侧来，现约朝原绿沙发方向。','两个固定手部视点硬切，以花园日光与室内冷暖光区别时空。',[(0,.14,'花园段停在母亲握稳已签文件的交接结束态，少女双手已松开退出，不重演递纸'),(.14,1.38,'硬切回现在庄园茶几；Serafina从自己座位侧伸出原操作手，触住同一现时合同的可及边缘，沿桌面向Eliza一侧再短距离推送'),(1.38,1.72,'纸停住，母亲手离开纸边沿原座位方向收回；旁边同一杯碟位置不变')],'回忆里的恭敬与现在的冷淡以动作力度对照：母亲推纸直接、没有安抚；不让她新增发怒或敲桌。',ESTLOCK+'回忆旧文件和现时合同用明确硬切隔开，不当作同一张纸连续穿时空。现约仍在原桌面，不凭闪回回到母亲手中；推送只在其手实际可及范围。','现时纸张在桌面短滑的轻响、庄园室内底声。',['现约在闪回前已经女主侧；本镜按批准动作保留母亲再次推纸，只从现有纸位短推，不补“先拿回母亲侧”或其他新动作。'])
add(30,'手轻轻落在退回的纸上',ESTATE,'合同特写硬切女主近景（CU）。','前段同一低茶几俯拍；后段略高从入口半区朝原绿沙发，Eliza面部与手在同一关系里，纸仍位于她前下方。','固定俯拍硬切固定女主近景。',[(0,.16,'延续合同已被短推到女主侧、母亲手正沿自己方向收回的纸面终态'),(.16,1.86,'硬切Eliza；她垂下眼睛，自己的原操作手伸向桌上那叠合同，掌面轻落在纸上，臀部仍留原绿沙发'),(1.86,2.24,'手掌贴纸停住，目光留在下方，纸不再来回滑动')],'她看见纸回来，眼神随之落低，手落得轻而迟疑；只有复杂的沉默，不加露齿笑、哭或求情。',ESTLOCK+'母亲手从左红椅方向退出、女主手从绿沙发方向入画，纸面反打不互换手的归属；手落纸不把合同带到膝上。','极轻手掌触纸声与安静大厅底声。')
checkpoint(21,30)

add(31,'母亲抬下巴等她屈从',ESTATE,'女主近景硬切母亲中景（MS）。','前段女主仍坐原绿沙发低头；后段同轴线入口半区朝左红椅取Serafina，母亲在画面左中，视线指向画右的女主。','固定近景硬切固定母亲中景，不加机位绕转。',[(0,.14,'保持Eliza手落在原合同上、目光低垂的近景'),(.14,1.22,'硬切Serafina；她仍在左红椅坐稳，原端杯手搭住同一杯壁，脸色收冷，下巴轻抬'),(1.22,1.56,'她把目光停在对面Eliza身上，嘴唇保持闭合，等下一镜才发言')],'母亲将即将说的话压在抬下巴与冷脸里，保持从容而难读；不能提前开口造成下一镜台词重复。',ESTLOCK+'杯一直属于母亲自己一侧，合同留女主侧桌面。母亲坐姿没有随近景站起，女主坐位仍在画外对面。','大厅环境底声、极轻杯壁与衣料声。')
add(32,'傲慢地宣布替代者',ESTATE,'母亲中景硬切正面近景（CU）。','在同一入口侧半区从左红椅前方略偏取正脸，Serafina看画右镜外绿沙发的Eliza；摄影机与她戏内注视点错开，不作直视镜头。','硬切收紧后缓慢推进，推幅只加强面部，不改变母亲椅中位置。',[(0,.18,'接母亲已抬下巴、尚未开口的中景尾态'),(.18,3.52,'硬切正面近景并缓推；她抬眼看对面Eliza，保持略高的下巴，以傲慢、故意清楚的态度说本镜原对白'),(3.52,3.96,'句尾眼神仍落在女主，不低头解释，也不做多余笑或点头')],'先抬眼再说话，神情是从容的轻视；语言抛出后脸色不软化，手与杯保持画外原状态，不另加指点或拍桌。',ESTLOCK+'母亲臀背有红椅承托，面部变近不改变身高或座位；画外女主仍坐绿沙发。','大厅自然底声及原杯的极轻接触声。')
add(33,'话落在她低下去的眼睛上',ESTATE,'母亲近景硬切女主近景（CU）正反打。','起段母亲原红椅正脸；后段从同一关系轴入口半区反打绿沙发Eliza，女主偏画面右，母亲方向在画左戏内，冷窗光从原高窗侧塑形。','固定正反打硬切，不越轴，不新增甩镜。',[(0,.16,'延续母亲上一句已结束的冷淡表情，不把前句从头再说'),(.16,2.34,'硬切女主；母亲本镜后续话声在画外响起，Eliza目光从对面母亲落回合同，睫毛轻颤，嘴唇仍闭合'),(2.34,2.80,'她停在垂眼隐忍的姿态，下颌轻绷又收住，不新增回应')],'言语先到，她的眼睛随后退向纸面，睫毛颤一下，情绪被咬住；不是无所谓，也不是大哭，画内女主不配母亲台词口型。',ESTLOCK+'女主仍由原绿沙发承托，桌上合同位置不动。正反打看向彼此戏内座位，不因直取面部变成对镜头发言。','克制的自然呼吸与大厅底声，母亲同场画外发言。')
add(34,'把杯放下，冷冷说完后半句',ESTATE,'女主近景硬切过女主肩的母亲中景（MS）。','女主坐姿右肩虚在画面右前，Serafina在画面左后同一红椅；相机在近侧女主外侧、入口同半区，保持真实坐姿过肩。','固定女主近景硬切固定过肩中景。',[(0,.14,'保留女主已经垂眼、睫毛收住的近景，不让她重复受刺激'),(.14,1.74,'硬切过肩母亲；Serafina把一直端着的原杯降向自己一侧杯碟，杯底先接触碟再放松持杯手，同时只说完前镜同一句的本镜片段'),(1.74,2.16,'她的手仍轻搭杯旁，下巴和冷眼停向女主，不移椅、不再端杯重做放下')],'杯落稳、话说完，动作与声音同样没有回旋；轻蔑通过从容的放杯和不回避女主的视线呈现，不增加敲杯或怒斥。',ESTLOCK+'杯碟有低茶几承托，手从母亲自身方向收势。女主的近肩高度属于坐在对面绿沙发的人，不把女主放成站在母亲身后的假过肩。','原杯落到碟上的轻响与大厅底声。')
add(35,'让合同承住一句命令',ESTATE,'母亲中景硬切合同大特写（ECU）。','起段母亲原红椅及已落杯；后段在同一低茶几上方俯拍女主侧合同，纸面朝女主，原笔在画面下缘。','固定中景硬切固定纸面，只有取景尺度变化。',[(0,.14,'承接母亲杯已放妥、手停杯旁的中景，不重复前镜句尾'),(.14,1.36,'硬切合同条款和原笔的大特写，纸与笔保持静止；母亲从画外说本镜短命令'),(1.36,1.68,'纸面继续停住，没人伸手签字，也不新添点纸动作')],'命令干脆而从容，切纸后没有脸部和多余口型；不把压迫演成突然拍桌或撕约。',ESTLOCK+'合同只是一叠原桌位纸件，笔一直在其下缘，不能复制成拼贴卡或让笔自动移动。纸面可见内容取真实资产，不生成旁白、标签或字幕。','自然大厅底声，母亲同场画外短句。')
add(36,'笃定的坐姿不动',ESTATE,'合同大特写硬切母亲近景（CU）。','前段同一低茶几纸与笔；后段在原红椅前方入口同半区取Serafina，视线向画右对面女主，人物不站起。','固定纸面硬切固定近景。',[(0,.12,'延续合同和笔静止的纸面终态'),(.12,1.04,'硬切Serafina；她保持双腿已经交叠的原坐姿，从原杯旁收回手，双手交叠在自己膝前，下巴轻抬'),(1.04,1.32,'折叠双手停住，眼神笃定而高傲，闭唇保持沉默')],'她确信对方会接受，抬下巴后不再追问，双手的安放显出不急不躁；不做得意大笑。',ESTLOCK+'母亲腿部原交叠关系保留，不在短镜中新增完整换腿动作；收手路线从自己的杯旁回膝前，杯与纸画外各留原桌位。','轻微衣料及大厅环境声。')
add(37,'十指扣紧，却没有求她',ESTATE,'母亲近景硬切女主略俯近景（CU）。','前段母亲原红椅；后段从入口同半区略高朝女主绿沙发前缘，女主脸与身前交握手同框，目光低向原桌面。','两个固定近景硬切，不增加旋转或压迫性俯冲。',[(0,.16,'保持母亲交叠双手、抬下巴的笃定近景'),(.16,2.14,'硬切Eliza；她在自己身前把十指交扣得更紧，手停桌缘可及的原身前高度，低下眼睛，不伸向母亲'),(2.14,2.60,'扣紧的双手保持原抓点，肩背有坐垫承托，脸上收住情绪')],'她的手指先结紧，眼睛随后低下，承受压力但不求饶；不是撒娇，不加哭腔、叹气或说话口型。',ESTLOCK+'女主双手在自己身前，不把低茶几抬到胸高，也不借近景把她移到红椅；母亲对面坐姿冻结。','指间与衣料极轻摩擦、安静大厅声。')
add(38,'母亲再次端杯，斜眼轻蔑',ESTATE,'女主近景硬切母亲中景（MS）。','前段女主绿沙发身前交握手；后段从入口半区朝左红椅，母亲在画面左，戏内女主在画右画外。','固定正反打硬切，不追杯另切特写。',[(0,.16,'延续女主双手紧扣、垂眼隐忍的姿态'),(.16,1.94,'硬切Serafina；她伸原持杯手从自己杯碟端起同一只杯，轻饮一口，目光横向斜睨对面Eliza'),(1.94,2.44,'她停在杯口附近的端杯姿态，斜睨里的轻蔑保留，身体仍在原椅')],'从容喝茶与横过来的眼神构成轻视，眼睛只看真实女主方向；不突然翻白眼，不增加台词或讥笑声。',ESTLOCK+'杯由母亲自己的手拿住，从原杯碟起，不越桌去抓女主侧道具。女主在反打画外维持原坐位，双手可自然收回膝前，不瞬移站起。','自然小口喝茶声、极轻瓷器及大厅声。')
add(39,'膝上的指节越扣越白',ESTATE,'母亲中景硬切女主手部大特写（ECU）。','前段母亲仍左红椅端杯；后段从女主外侧略俯取她自己膝上交握的双手，方向与绿沙发坐位一致。','固定中景硬切固定手部插镜。',[(0,.12,'保持母亲端杯斜睨的中景尾态；女主在画外把交握的手收回自己膝上'),(.12,1.20,'硬切女主膝上双手；原先交握的手指进一步收紧，指节因压力逐渐泛白，手腕仍贴自己的腿'),(1.20,1.52,'手停在绷紧状态，膝与坐垫提供承托，不继续新增抓衣或掐手动作')],'难堪、感念与克制只通过同一抓握的加力呈现；不需要女主的脸再做第二次哭笑反应。',ESTLOCK+'画面中两只手均属于Eliza，母亲持杯的手不能接成女主手。由身前收回膝上的路线在前段女主画外完成，落点不悬空。','极轻衣料声与自然环境底声，不加夸张握拳音效。')
add(40,'把两人的距离重新放回大厅',ESTATE,'女主手部大特写硬切客厅大远景（ELS）。','前段女主膝上双手；后段在大厅入口侧上空高角度斜拍原会谈区域，母亲左红椅、女主远处绿沙发，女主背肩朝镜头而头略低，低茶几在中间。','硬切拉开视野，后段大远景固定；并非摄影机从手部穿越房间后拉。',[(0,.16,'保留膝上双手已经扣紧的终态，手不再另换抓点'),(.16,2.72,'硬切高斜客厅大远景；两人仍隔同一低茶几而坐，Eliza身形缩在绿沙发前缘，Serafina在左红椅保持从容，既有灯光在空间内安静存在'),(2.72,3.20,'整个会谈构图停住，留原来的沉默与距离，谁也不站起或换位')],'母亲从容、女主承受的反差由两人不动的姿态及空间大小保留；不添加突然抬头、回望或求情。',ESTLOCK+'镜头只在入口半区上空，右楼梯和左拱门不互换；近处大圆桌花瓶与会谈低茶几各留自身位置，不添加壁炉火光。','安静大厅环境声，不添加火声或音乐。')
