add(41,'把手放回桌上，低下眼睛',ESTATE,'会谈大远景硬切女主近景（CU）。','起段保持大厅入口侧高斜全貌；后段在同一会谈轴入口半区跨低茶几朝绿沙发Eliza取近景，手与原桌缘在画面下方可理解。','固定大远景硬切固定近景，不加额外摇移。',[(0,.18,'延续母亲左红椅、女主绿沙发隔桌坐着的宽景终态'),(.18,2.86,'硬切Eliza；她把交握的手松开到原来的接触程度，将原操作手从自己膝前伸回可及桌缘，掌面落平，目光随之垂下'),(2.86,3.56,'手留在原桌缘或合同旁，眼神停住，面上的感念与难过没有立即化成一个单一表情')],'想到被支持的过往，眼里先有复杂的停顿，再把目光按回桌面；不无故微笑、不新增流泪，唇闭合。',ESTLOCK+'女主仍坐原绿沙发前缘，手从自己膝前到桌缘有真实路线，不能靠切镜凭空出现在桌上；母亲仍对面原椅，纸件不换位置。','掌面触桌及轻微衣料声，大厅自然底声。')
add(42,'抬眼一瞬，又盯住合同',ESTATE,'女主近景硬切正面更近的近景（CU）。','仍从入口同半区对原绿沙发取正脸，戏内母亲在画左画外，合同在女主前下方；两段的面部朝向与身体座位一致。','硬切后缓慢推进到面部，不增加第二次抬头或另一个角度。',[(0,.50,'在原近景中Eliza抬起眼睛和下巴，向对面母亲看一瞬，手仍在原桌缘'),(.50,2.92,'硬切更近正面并缓推；她缓缓低头，目光移回同一合同，腰部只作原坐姿小幅前倾'),(2.92,3.72,'她停在凝视纸面的姿态，肩髋不再移动，镜头保留眼里的分量')],'不是认输般垮掉，而是把母亲、旧日恩情与纸上约定同时看进眼里；抬眼的迟疑收成漫长的低头，不叹气、不做说话口型。',ESTLOCK+'臀部与背部仍有沙发支撑，下颌低向纸面而非胸口压到底；手、合同和杯的画外位置与前镜一致，不提前起立。','近乎安静的大厅环境底声。')
add(43,'从纸上凝视切入旧日推门',ESTATE+'硬切后进入明亮日照的庄园铁门旧日记忆。','现时女主近景硬切第一人称手与铁门特写（CU）。','前段沿原绿沙发女主低头的近景；后段为站在原铁门外、朝门内花园看的第一人称视点，只见女主原入画手和门扇。','现时固定近景硬切固定第一人称推门视点，不新增穿门飞行。',[(0,.12,'保留女主坐绿沙发低头凝视原合同的终态'),(.12,.92,'硬切明亮记忆；原入画的一只女主手先贴住铁门可施力位置，再向门内推，门扇沿真实铰链转动，亮处从开启门缝中显露'),(.92,1.12,'保留门扇继续打开的末段，操作手仍与门接触，不凭空消失或更换手')],'只通过手掌先落稳再推开的动作进入记忆；不给未出镜的脸另加青年表情，也不让手替人物说话。','现时坐姿与旧日第一人称为明确硬切，不是女主从沙发瞬移到门外。铁门结构按庄园大门资产，手由女主本人身体方向伸入，力量使门绕铰链而非平移脱框。','铁门铰链原有轻响与花园自然环境声。',['源仅一只推门手且无脸，沿批准稿不推断新的青年年龄或擅加另一只手；当前女主身份只作手部归属。'])
add(44,'旋转记忆后，纸被撕开',BED+'此为旧日碎片回忆，床面受同一卧室既有暖光照亮。','旋转模糊转场硬切撕纸手部特写（CU）。','先保留原径向旋转模糊；后段从床右通道取原床面上方的Matteo双手，原上方手与下方手各握纸的一端，不新增面部。','径向漩涡模糊仅作原转场效果；硬切后手部机位固定，不把模糊当成身体旋转。',[(0,.12,'保留源径向漩涡模糊转场，不在模糊中新增人物动作'),(.12,.84,'硬切原床面上方手部；Matteo的两只手分别捏住原纸张或书页的两侧，承接已经施力的抓点，沿原裂口对向拉开，纸分成两片，松散碎屑向床面下落'),(.84,1.00,'两手各留一片撕开的纸，碎屑继续受重力落在同一被面，手不交换原上、下位置')],'动作短、利落而带否定意味，只在纸的受力和撕裂上显出态度；不额外露出脸、纹身或替他增加喊话。','仅拍男主双手及原纸、床面，手臂归同一Matteo，身体阶段不由局部另行猜测。撕的是源纸张或书页，不替换成现时续约纸；床品外观沿卧室资产，纸片真实下落。','原纸撕裂声、转场原轻掠声、碎纸落床轻响。',['旧批准英文误写一只手；已实看源S44尾卡，两手各握撕开纸片。经主线程确认按真实受力改成双手，镜号、1.00秒、转场硬切、撕纸和碎屑下落均不变，非新增表演。'])
add(45,'她仍停在卧室门框旁',BED+'回忆中的暖色实景灯保留原门口的孤独感，灯具位置仍按资产。','撕纸手部特写硬切女主门边中景（MS）。','前段仍原床面上方男主双手与纸片；后段从床右通道望床尾右入口，成年Eliza侧对摄影机，原近门的一只手搭在同一门框。','两个固定视点硬切，不沿纸片飞行穿过房间。',[(0,.12,'承接男主双手各握纸片、碎屑向原床面落下的末段，不重撕一次'),(.12,1.02,'硬切Eliza门边中景；她双脚落在床尾右门后地面，一只手已经搭着门框，身体轻靠框边，脸上的情绪慢慢落下'),(1.02,1.28,'她停在同一侧身门边姿态，手不松框，不再迈步或探身')],'被留在门边的落寞通过脸色低下与轻靠的肩背呈现；不加哭、苦笑、叹气或回头说话。','这是指定成年睡衣资产的回忆段，不切成18岁校园人物。门在床尾右入口，床仍左靠墙、右道可用；女主主要重量由双脚承担，搭框手只有支撑与停留，不悬挂身体。','安静卧室底声、轻微原地板承重声。')
add(46,'门缝里只剩她的脚',BED,'女主门边中景硬切门外低位腿脚特写。','起段同一床尾右门框；后段相机在该门外贴近地板，透过已半掩的同一门缝，只取Eliza门后下腿和双脚，暖光来自原室内。','固定中景硬切固定低机位，不追加一段关门动作。',[(0,.10,'保留Eliza在门框边轻靠、脸色低落的中景尾态'),(.10,.60,'硬切同一门外低位；门已经半掩，暖光形成原门缝亮带，Eliza双脚仍站在门后，只作一次很小的重心挪动'),(.60,.80,'脚跟与前掌落稳后停止，门缝及室内光保持不动')],'不露脸，只有脚步未走开而又停住的迟疑；不把短镜扩成转身离去或重新开关门。','门框、门扇和脚落点属于同一床尾右入口，脚始终有地板承托；腿脚仅取女主资产，不另设计服装具体款式。门的半掩首态在切点外成立，不让门穿过女主的腿。','轻微脚底承重、室内自然底声。',['门由前镜门框视角到本镜半掩状态的关合过程不在源镜里；按批准首态执行，不擅加完整关门。'])
add(47,'回到现在，认真看向母亲',ESTATE,'记忆门缝腿脚特写硬切现在女主近景（CU）。','前段仍同一卧室门外低机位；后段回到庄园入口同半区朝绿沙发Eliza取近景，她看画左对面原红椅的母亲。','固定门缝硬切固定面部，记忆与现在明确分隔。',[(0,.14,'保留门缝暖光及门后女主双脚停稳的记忆尾态'),(.14,1.62,'硬切现在成年Eliza日常资产；她仍坐原绿沙发，双手在身前交握，抬眼看母亲，双唇自然分开说本镜原对白片段'),(1.62,1.92,'她保持认真的目光与坐姿，句意接向下一镜，不另做第二次准备开口')],'长久沉默后，她先抬起眼睛再开口，郑重里有已经决定好的分量；不是卑微讨好，也不先笑着缓和气氛。',ESTLOCK+'成年阶段及外观在硬切处恢复日常资产，不把门后脚或卧室灯带进客厅；双手交握属于同一女主，臀部留原坐垫。','安静大厅声、自然轻呼吸。')
add(48,'把合同推回去，慢慢摇头',ESTATE,'女主近景硬切俯拍女主与合同的中景（MS）。','前段女主看向画左母亲；后段在原关系轴入口同半区略高俯拍低茶几，女主在画面右侧原绿沙发前缘，手纸在下方，头部仍在上缘可见以保留摇头。','固定近景硬切固定俯拍关系中景，不把推纸变成空中抛纸。',[(0,.14,'接女主已开始同一句的近景，眼神仍朝母亲，不重复上一镜片段'),(.14,2.14,'硬切俯拍中景；Eliza自己的原操作手先贴住合同，再沿桌面把纸推向对面母亲侧，同时缓缓摇头，身体仍由绿沙发托住，声音连续说本镜原文片段'),(2.14,2.60,'合同在母亲侧可及处停住，女主手仍贴着纸边，摇头收住而目光没有躲开')],'感念的语气与拒绝的手势同时存在：纸推得平稳，摇头很小但清楚，不能演成愤怒扔纸或撒娇试探。',ESTLOCK+'推纸手从女主绿沙发方向来，纸朝原左红椅方向去。先接触再施力，纸底始终贴桌，杯与笔留既定落点；拍到头部才表现摇头，不在纯手部镜要求不可见表情。','纸张沿桌面滑回的轻响、自然呼吸及大厅声。')
add(49,'抬起头说出不续约',ESTATE,'俯拍手纸关系中景硬切女主近景（CU）。','起段合同在已推回母亲侧、女主手贴纸；后段从入口同半区看原绿沙发Eliza，母亲在画左戏内，不用视线直射镜头。','硬切固定近景，不额外上摇或围绕。',[(0,.12,'保留合同已经推回、女主手仍按着纸边的终态，不再重新推一次'),(.12,1.34,'硬切Eliza；她抬起头朝母亲，眉心轻轻聚起，用本镜原对白明确拒绝续约'),(1.34,1.64,'句尾嘴唇收住，眼睛仍望对面，臀背不离绿沙发')],'眉间是认真与被触动后的疼，不是讨价还价；抬头后说得清楚，不笑、不放狠话，也不补哭诉。',ESTLOCK+'女主手与纸的画外落点冻结在已推回的位置，不把纸又拿回自己膝上；她只抬头而不因近景忽然站立。','原大厅自然底声。')
add(50,'把决定说到底',ESTATE,'女主近景硬切正面更近的近景（CU）。','同一绿沙发坐位取略偏正面，摄影机与母亲实际注视点错开；女主目光朝画左对面，合同在原低茶几画外。','固定近景硬切固定更近正面，不用运镜替代源剪切。',[(0,.12,'保留女主眉心轻聚、目光已经抬向母亲的近景'),(.12,1.28,'硬切更近正面；Eliza下巴稳住，直视戏内母亲，把本镜原对白完整说清'),(1.28,1.56,'话尾唇闭合、目光不退，保持同一坐姿，为下一镜接入男主的全景留终态')],'拒绝已经落定，声音平静而坚定，眼里仍有受过伤后的分量；不把坚定演成冷笑或突然站起。',ESTLOCK+'女主没有在景别切换中换座、站起或把手离纸另做动作；下颌和目光的变化只属于原坐姿，母亲在原左红椅画外。','原大厅自然底声。')
