assert len(rows)==54
assert [r['source_id'] for r in rows]==[s['source_id'] for s in src]
assert all(r['duration']==s['duration'] and r['asset_names']==s['asset_names'] for r,s in zip(rows,src))
fields=['时长','环境氛围','景别','拍摄角度','摄像机运动','人物角色和运动','人物表演','画面内容','音频']
errors=[]
dialogue_count=0
for r,s in zip(rows,src):
 text=r['new_prompt']
 present=re.findall(r'^(时长|环境氛围|景别|拍摄角度|摄像机运动|人物角色和运动|人物表演|画面内容|音频)：',text,re.M)
 if present!=fields: errors.append((r['source_id'],'field_order',present))
 if s['source_has_internal_hard_cut'] and '硬切' not in text: errors.append((r['source_id'],'missing_internal_cut'))
 audio=text.split('\n音频：',1)[1]
 elsewhere=text.split('\n音频：',1)[0]
 for d in s['dialogue']:
  dialogue_count+=1
  if audio.count('"'+d['text']+'"')!=1: errors.append((r['source_id'],'dialogue_missing_or_duplicate',d['text']))
  if d['text'] in elsewhere: errors.append((r['source_id'],'dialogue_outside_audio',d['text']))
 expected=[d['text'] for d in s['dialogue']]
 got=re.findall(r'"([^"]+)"',audio)
 if got!=expected: errors.append((r['source_id'],'unexpected_quoted_words',got))
 other='\n'.join(l for l in text.splitlines() if not l.startswith(('人物角色和运动：','时长：')))
 if re.search(r'\d+(?:\.\d+)?[—–-]\d+(?:\.\d+)?秒',other): errors.append((r['source_id'],'time_outside_action'))
 for a,b,t in phase_index[r['source_id']]:
  if b-a<=0: errors.append((r['source_id'],'nonpositive_phase'))
 if any(w in text for w in ('FIRST FRAME:','STIMULUS→','POSITION LOCK:','LIGHTING:','AUDIO:')): errors.append((r['source_id'],'old_format'))
 if any(w in text for w in ('Dante','Elena','DeLuca')): errors.append((r['source_id'],'old_identity'))
 if any(w in text for w in ('\u5fae\u5fae\u4ef0\u5929\u957f\u53f9','身穿黑色','白色衬衫','丝绸睡袍','碎花裙','黑色睡衣')): errors.append((r['source_id'],'costume_description'))

source_sha=hashlib.sha256(SOURCE.read_bytes()).hexdigest()
out=BASE/'EP08_新版提示词.json'
report=dict(status='PASS_LOCAL_EP08_FORMAT_REWRITE' if not errors else 'FAIL',source_path=str(SOURCE),source_sha256=source_sha,output_path=str(out),output_sha256=hashlib.sha256(out.read_bytes()).hexdigest(),shot_count=len(rows),duration_seconds=round(sum(r['duration'] for r in rows),2),internal_hard_cut_count=sum(bool(s['source_has_internal_hard_cut']) for s in src),dialogue_shot_count=sum(bool(s['dialogue']) for s in src),dialogue_fragment_count=dialogue_count,source_ids_and_assets_unchanged=True,all_actions_cover_zero_to_duration=True,time_ranges_only_in_action=True,dialogue_exact_and_audio_only=True,old_english_format_removed=True,narration_removed=True,no_ui_operation=True,notes=['内部切点为本次提示词执行分配，并非源逐帧实测；原镜顺序、时长及前后视点全部保留。','S44按源首尾卡及主线程明确确认改正旧英文的单手/双手矛盾，不改撕纸剧情。','全部新提示词为本地派生稿；不证明剧梦已保存、绑定或生成。'],issues=[dict(source_id=r['source_id'],items=r['issues']) for r in rows if r['issues']],errors=errors)
(BASE/'EP08_新版提示词_自查.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(BASE/'EP08_新版提示词_动作分段校验.json').write_text(json.dumps(phase_index,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({k:report[k] for k in ['status','shot_count','duration_seconds','internal_hard_cut_count','dialogue_shot_count','dialogue_fragment_count','errors']},ensure_ascii=False),flush=True)
if errors: raise SystemExit(2)
